def market_episode_returns(market_prices: pd.DataFrame, spine_episodes: pd.DataFrame) -> pd.DataFrame:
    px = market_prices.copy()
    px['date'] = pd.to_datetime(px['date'])
    ep = spine_episodes.copy()
    ep['start_date'] = pd.to_datetime(ep['start_date'])
    rows = []
    for _, e in ep.iterrows():
        t0 = e['start_date']
        t1 = t0 + pd.Timedelta(days=20)
        win = px[(px['date'] >= t0) & (px['date'] <= t1)]
        for entity, g in win.groupby('market_id', sort=True):
            g = g.sort_values('date')
            if len(g) < 2:
                continue
            first = float(g['price'].iloc[0])
            last = float(g['price'].iloc[-1])
            if first == 0.0:
                continue
            rows.append({
                'market_id': entity,
                'episode': e['episode'],
                'return_pct': last / first - 1.0,
            })
    out = pd.DataFrame(rows)
    out = out[['market_id', 'episode', 'return_pct']]
    return out.sort_values(['market_id', 'episode']).reset_index(drop=True)

def market_action_data(market_episode_returns: pd.DataFrame, spine_markets: pd.DataFrame) -> pd.DataFrame:
    out = market_episode_returns.merge(spine_markets, on=['market_id'], how='inner')
    out = out[['market_id', 'episode', 'asset_class', 'return_pct']]
    return out.sort_values(['market_id', 'episode']).reset_index(drop=True)
